const decode=(v:any):any=>Array.isArray(v)?v.map(decode):v&&typeof v==='object'?('__text' in v?strings[v.__text]:Object.fromEntries(Object.entries(v).map(([k,x])=>[k,decode(x)]))):v;
const patches=decode(encoded) as unknown as Record<string,{before:Pick<Rule,'scenario'|'approveFacts'|'rejectFacts'|'lawText'|'note'>;after:Rule&{held:boolean}}>;
const canonical=(value:unknown):string=>JSON.stringify(value,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b))):v);
export function correctKnownMedicalRule(rule:Rule):Rule|null{
 if(rule.auditVersion)return rule;
 const patch=patches[rule.id];if(!patch)return rule;
 const signature={scenario:rule.scenario,approveFacts:rule.approveFacts,rejectFacts:rule.rejectFacts,lawText:rule.lawText,note:rule.note};
 if(canonical(signature)!==canonical(patch.before))return rule;
 return patch.after.held?null:{...rule,...patch.after};
}
